"""Mahagauri `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def cell(value) -> str:
    return "—" if value is None else (f"{value:.0f}" if isinstance(value, float) and value.is_integer() else f"{value}")


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d, p = r["dataset"], r["protocol"]
    out = [
        "<!-- Generated by packages/sati/sati/verify/report.py from the training workflow. Do not edit by hand. -->\n",
        "# Mahagauri v0 — has the server really returned to normal?\n",
        f"**{d['name']}** ({d['repo']} @ `{d['revision'][:12]}`): {d['incidents']} real incidents with an hour of clean "
        f"history before them. From each incident's first minute until {p['horizon_minutes']} minutes after it ends, "
        f"the verifier answers once a minute whether the server has recovered. It declares *all clear* at the first "
        f"of {p['consecutive']} consecutive yeses. Each machine group is held out in turn, and every threshold is set "
        f"on the other groups so that premature all-clears stay at or below {p['premature_budget']:.0%} there.\n",
        "## Pooled over held-out groups\n",
        "| Verifier | Premature all-clear ↓ | Confirmed | Unconfirmed in the hour |",
        "|---|---:|---:|---:|",
    ]
    for name, s in r["pooled"].items():
        label = f"**{name}**" if name.startswith("mahagauri") else name
        out.append(f"| {label} | {s['premature_rate']:.3f} | {s['confirmed_rate']:.3f} | {s['unconfirmed_rate']:.3f} |")
    out += ["", "## Per held-out group\n",
            "| Held out | Incidents | Verifier | Premature | Confirmed | Unconfirmed | Median delay (min) |",
            "|---|---:|---|---:|---:|---:|---:|"]
    for f in r["folds"]:
        for name, s in f["verifiers"].items():
            out.append(f"| `{f['held_out']}` | {f['incidents']} | {name} | {s['premature_rate']:.3f} | "
                       f"{s['confirmed_rate']:.3f} | {s['unconfirmed_rate']:.3f} | {cell(s['median_delay'])} |")
    out += [
        "",
        "## How to read this\n",
        "- A **premature all-clear** is the error that matters: the incident is declared over while it continues. "
        "A verifier that never declares anything has a premature rate of zero and is useless, so read the "
        "confirmed share next to it.",
        "- *Back within 3σ* is what a hand-written check amounts to: every metric back near its pre-incident level. "
        "The *fixed timer* waits for the median incident length seen in training.",
        "- SMD's labels mark when operators judged each anomaly over. Those labels are the ground truth here, "
        "and they inherit the operators' judgement.",
        "- Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
